// Generated by php2rust. In release builds set overflow-checks = true, see the README.

pub fn show(value: bool) -> String {
    return (if value { "yes" } else { "no" }).to_string();
}

pub fn kind(text: &str) -> String {
    if php_preg_match(r"(?-u)^\d+\z", text) {
        return String::from("number");
    } else if !php_preg_match(r"(?-u)[^a-z]", text) && text != "" {
        return String::from("word");
    }
    return (if php_preg_match(r"(?-u)\s", text) || text == "" {
        "spaced"
    } else {
        "other"
    })
    .to_string();
}

pub fn to_last_line(text: &str) -> i64 {
    let mut text = text.to_string();
    let mut steps: i64 = 0;
    while php_preg_match(r"(?-u)\n", &text) {
        text = php_substr(&text, 1, None);
        steps += 1;
    }
    return steps;
}

pub fn first_digit(text: &str) -> i64 {
    let mut text = text.to_string();
    let mut at: i64 = 0;
    while at < text.len() as i64 && !php_preg_match(r"(?-u)\d", &php_substr(&text, at, Some(1))) {
        text += "";
        at += 1;
    }
    return at;
}

pub fn flags(text: &str) -> String {
    let none = !php_preg_match(r"(?-u)a", text);
    return format!(
        "{}{}",
        if php_preg_match(r"(?-u)b", text) {
            "b"
        } else {
            "-"
        },
        if none { "no-a" } else { "a" }
    );
}

pub fn compared(text: &str) -> String {
    let parts = vec![
        php_preg_match(r"(?-u)a", text),
        php_preg_match(r"(?-u)a", text),
        !php_preg_match(r"(?-u)a", text),
        !php_preg_match(r"(?-u)a", text),
        php_preg_match(r"(?-u)a", text),
        php_preg_match(r"(?-u)a", text),
        !php_preg_match(r"(?-u)a", text),
        !php_preg_match(r"(?-u)a", text),
    ];
    let mut out = String::from("");
    for &part in &parts {
        out += &format!("{} ", show(part));
    }
    return out;
}

fn php_substr(text: &str, start: i64, length: Option<i64>) -> String {
    let size = text.len() as i64;
    if start > size {
        return String::new();
    }
    let start = if start < 0 {
        (size + start).max(0)
    } else {
        start
    };
    let rest = size - start;
    let length = match length {
        Some(length) if length < 0 => (rest + length).max(0),
        Some(length) => length.min(rest),
        None => rest,
    };
    let (from, to) = (start as usize, (start + length) as usize);
    String::from_utf8_lossy(&text.as_bytes()[from..to]).into_owned()
}

fn php_preg_match(pattern: &str, subject: &str) -> bool {
    ::regex::bytes::Regex::new(pattern)
        .expect("php2rust checked this pattern")
        .is_match(subject.as_bytes())
}

fn main() {
    print!("{}", kind("123"));
    print!(" ");
    print!("{}", kind("abc"));
    print!(" ");
    print!("{}", kind("a b"));
    print!(" ");
    print!("{}", kind("A1!"));
    print!("\n");
    print!("{}", to_last_line("a\nb\nc"));
    print!("\n");
    print!("{}", first_digit("ab3c"));
    print!(" ");
    print!("{}", first_digit("abc"));
    print!("\n");
    print!("{}", flags("ab"));
    print!(" ");
    print!("{}", flags("c"));
    print!("\n");
    print!("{}", compared("cat"));
    print!("\n");
    print!("{}", compared("dog"));
    print!("\n");
}
